private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        return i;
    }
    int limit = bb.limit();
    if (i < 0 || i >= limit) {
        return i;
    }
    int b0 = bb.get(i) & 0xFF;
    int codePoint;
    int length = 1;
    if (b0 < 0x80) {
        codePoint = b0;
    } else if ((b0 >> 5) == 0x6) { // 110xxxxx
        if (i + 1 >= limit) {
            codePoint = 0xFFFD;
        } else {
            int b1 = bb.get(i + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                codePoint = 0xFFFD;
            } else {
                codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
                length = 2;
            }
        }
    } else if ((b0 >> 4) == 0xE) { // 1110xxxx
        if (i + 2 >= limit) {
            codePoint = 0xFFFD;
        } else {
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
                codePoint = 0xFFFD;
            } else {
                codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
                length = 3;
            }
        }
    } else if ((b0 >> 3) == 0x1E) { // 11110xxx
        if (i + 3 >= limit) {
            codePoint = 0xFFFD;
        } else {
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            int b3 = bb.get(i + 3) & 0xFF;
            if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
                codePoint = 0xFFFD;
            } else {
                codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
                length = 4;
            }
        }
    } else {
        codePoint = 0xFFFD;
    }

    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        int cp = codePoint - 0x10000;
        char high = (char) ((cp >> 10) + 0xD800);
        char low = (char) ((cp & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }
    return i + length;
}

