@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }
    Collection<V> vertices = resultMap.values();
    if (vertices.size() < 2) {
        return; // Not enough vertices to form a bipartite graph
    }
    // Add all vertices to the target graph
    for (V v : vertices) {
        target.addVertex(v);
    }
    // Split vertices into two groups for the bipartite sets
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    int mid = n / 2;
    List<V> left = vertexList.subList(0, mid);
    List<V> right = vertexList.subList(mid, n);
    // Add edges between every vertex in left and every vertex in right
    for (V l : left) {
        for (V r : right) {
            target.addEdge(l, r);
        }
    }
}

