public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) return null;
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(targetType);
    Class<?>[] result = new Class<?>[args.length];
    for (int i=0; i<args.length; i++) {
        Type arg = args[i];
        // Resolve type variable
        if (arg instanceof TypeVariable) {
            Type resolved = typeVarMap.get(arg);
            if (resolved == null) return null;
            arg = resolved;
        }
        // If arg is still TypeVariable after map? maybe nested? we can attempt to resolve recursively
        // but for simplicity, if arg instanceof TypeVariable, return null
        if (arg instanceof TypeVariable) return null;
        Class<?> raw = getRawClass(arg);
        if (raw == null) return null;
        result[i] = raw;
    }
    return result;
}

