private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    // start with clazz
    while (clazz != null) {
        // process superclass
        Type genericSuper = clazz.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) genericSuper;
            Class<?> superClass = (Class<?>) pt.getRawType();
            TypeVariable<?>[] vars = superClass.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i=0; i<vars.length; i++) {
                map.put(vars[i], args[i]);
            }
        }
        // process interfaces
        for (Type iface : clazz.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pt = (ParameterizedType) iface;
                Class<?> ifaceClass = (Class<?>) pt.getRawType();
                TypeVariable<?>[] vars = ifaceClass.getTypeParameters();
                Type[] args = pt.getActualTypeArguments();
                for (int i=0; i<vars.length; i++) {
                    map.put(vars[i], args[i]);
                }
            }
        }
        clazz = clazz.getSuperclass();
    }
