    String path = rawPath.substring(start);
    if (path.isEmpty()) {
        return result;
    }
    String[] segments = path.split("/");
    for (String seg : segments) {
        if (seg.isEmpty()) {
            continue;
        }
        String decoded = seg;
        if (decode) {
            try {
                decoded = URLDecoder.decode(seg, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; fall back to raw segment
