protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new IllegalArgumentException("Cannot convert String of length " + str.length() + " to Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) candidate++;
    while (true) {
        boolean isPrime = true;
        if (candidate <= 3) {
            isPrime = true;
        } else {
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                isPrime = false;
            } else {
                int i = 5;
                int w = 2;
                while (i * i <= candidate) {
                    if (candidate % i == 0) {
                        isPrime = false;
                        break;
                    }
                    i += w;
                    w = 6 - w;
                }
            }
        }
        if (isPrime) return candidate;
        candidate += 2;
        if (candidate < 0) return Integer.MAX_VALUE; // guard against overflow
    }
}

