public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape \uXXXX
                    int j = i + 2;
                    int end = Math.min(j + 4, len);
                    if (end - j == 4) {
                        String hex = str.substring(j, end);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i = end - 1;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        // Octal escape up to three digits
                        int octal = next - '0';
                        int digits = 1;
                        int k = i + 2;
                        while (k < len && digits < 3 && str.charAt(k) >= '0' && str.charAt(k) <= '7') {
                            octal = (octal << 3) + (str.charAt(k) - '0');
                            k++;
                            digits++;
                        }
                        sb.append((char) octal);
                        i = k - 1;
                    } else {
                        // Unknown escape, keep the character as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

