final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    int offset;
    try {
        offset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    } catch (Exception e) {
        throw new IllegalArgumentException("Unable to locate constant pool entry", e);
    }
    if (offset < 0 || offset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid offset for constant pool entry");
    }
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException("Entry at index is not CONSTANT_Utf8");
    }
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small for UTF8 entry");
    }
    byte[] bytes = new byte[length];
    System.arraycopy(classFileBuffer, offset + 3, bytes, 0, length);
    String str = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    str.getChars(0, str.length(), charBuffer, 0);
    return new String(charBuffer, 0, str.length());
}

private static char decodeHexNibble(final char c) {
    if ('0' <= c && c <= '9') {
        return (char) (c - '0');
    } else if ('a' <= c && c <= 'f') {
        return (char) (c - 'a' + 10);
    } else if ('A' <= c && c <= 'F') {
        return (char) (c - 'A' + 10);
    } else {
        return Character.MAX_VALUE;
    }
}

public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("long overflow");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate");
    }
    if (start == null) {
        throw new NullPointerException("start");
    }
    if (stop == null) {
        throw new NullPointerException("stop");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If start already satisfies the predicate or is the stop node, return it immediately.
    if (start.equals(stop) || predicate.test(start)) {
        return circ;
    }
    // Traverse the outer face until we hit the stop node or find a node that satisfies the predicate.
    while (true) {
        circ.next(); // advance to the next node in the specified direction
        Node current = circ.getNode();
        if (current.equals(stop) || predicate.test(current)) {
            return circ;
        }
        // If we loop back to the starting node without finding the stop node, break to avoid an infinite loop.
        if (current.equals(start)) {
            return new OuterFaceCirculator(stop, dir);
        }
    }
}

