private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        // Verify that the node is actually part of this list
        if (node.prev == null && node.next == null && node != first && node != last) {
            return false;
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            first = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            last = node.prev;
        }
        // Help GC by clearing references
        node.prev = null;
        node.next = null;
        size--;
        return true;
    } catch (Exception e) {
        // In case of any unexpected error, indicate failure
        return false;
    }
}

