    // Build a sorted set of the keys (ignoring nulls)
    TreeSet<K> sortedSet = new TreeSet<>((a, b) -> {
        if (a == null && b == null) return 0;
        if (a == null) return -1;
        if (b == null) return 1;
        return ((Comparable)a).compareTo(b);
    });
    for (K k : keys) {
        if (k != null) {
            sortedSet.add(k);
        }
    }
    for (K key : keys) {
        if (key == null) {
            result.add(Integer.MIN_VALUE);
            continue;
        }
        K lower = sortedSet.lower(key);
        result.add(lower != null ? (Integer) lower : Integer.MIN_VALUE);
    }
    return result;
}

