        return all;
    }
    for (ThreadSnapshot snapshot : all) {
        long ts = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range.contains(ts)) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}

